// --- NEW FADE SLIDESHOW COMPONENT ---
function FadeSlideshow({ images, interval = 3000 }) {
  const [currentIndex, setCurrentIndex] = useState(0)
  
  useEffect(() => {
    // Set up the automatic transition
    const timer = setInterval(() => {
      setCurrentIndex(prevIndex => (prevIndex + 1) % images.length)
    }, interval)

    // Clean up the interval when the component unmounts or images change
    return () => clearInterval(timer)
  }, [images.length, interval])

  if (images.length === 0) {
    return <div className="slideshow-error">No images provided.</div>
  }

  return (
    <div className="slideshow-container">
      {images.map((imageSrc, index) => (
        <img
          key={index}
          src={imageSrc}
          alt={`Slide ${index + 1}`}
          // Use a className to manage the fade transition in CSS
          className={`slideshow-image ${index === currentIndex ? 'active' : ''}`}
          draggable={false}
          // Note: Error handling for individual images is removed for simplicity
          // but could be added back if needed.
        />
      ))}
    </div>
  )
}
